#include <QtWidgets>
void ResearchCompaniesPage::openGraphRelation(QString topic,QString id){
 // Embedded report graphs keep their drafts separate from the original standalone editor.
 const auto key=QCryptographicHash::hash((topic+QChar(0)+id).toUtf8(),QCryptographicHash::Sha256).toHex();
 const auto path=QFileInfo(store->filePath()).absolutePath()+"/sector-relation-graph-drafts-"+QString::fromLatin1(key)+".json";
 if(property("sectorRelationDraftPath").toString()!=path){
  setProperty("sectorRelationDraftPath",path);setProperty("sectorRelationDraftBlocked",false);setProperty("sectorRelationDraftIssue",QString());setProperty("sectorRelationDraftExpectedHash",QByteArray());drafts={};
  QFileInfo info(path);setProperty("sectorRelationDraftExpectedExists",info.exists());
  if(info.exists()){
   QFile file(path);QString issue;
   if(!info.isFile()||info.size()>4*1024*1024||!file.open(QIODevice::ReadOnly))issue="已有关系图草稿无法完整读取，原文件已保留，不会覆盖。";
   else{auto data=file.readAll();QJsonParseError error;auto doc=QJsonDocument::fromJson(data,&error);
    if(file.error()!=QFileDevice::NoError||data.size()!=info.size()||error.error!=QJsonParseError::NoError||!doc.isObject()||doc.object()["schema"]!="research-company-drafts/v1"||!doc.object()["drafts"].isObject())issue="已有关系图草稿格式异常，原文件已保留，不会覆盖。";
    else{setProperty("sectorRelationDraftExpectedHash",QCryptographicHash::hash(data,QCryptographicHash::Sha256));restoreState(doc.object());}}
   if(!issue.isEmpty()){setProperty("sectorRelationDraftBlocked",true);setProperty("sectorRelationDraftIssue",issue);}
  }
 }
 setTopic(topic);stage->setCurrentIndex(0);status->setCurrentIndex(0);search->clear();reload();select(id);if(auto tabs=findChild<QTabWidget*>())tabs->setCurrentIndex(1);
 if(property("sectorRelationDraftBlocked").toBool())state->setText(property("sectorRelationDraftIssue").toString());
}
ResearchCompaniesPage::ResearchCompaniesPage(std::shared_ptr<BusinessStore> s,QWidget* parent):QWidget(parent),store(std::move(s)){
 setObjectName("researchCompaniesPage");auto root=new QVBoxLayout(this);auto toolbar=new QHBoxLayout;topics=new QComboBox(this);topics->setObjectName("companyTopics");toolbar->addWidget(topics,1);stage=new QComboBox(this);stage->setObjectName("companyStage");stage->addItem("全部环节","");for(auto key:researchCompanies::stages())stage->addItem(researchCompanies::stageLabel(key),key);toolbar->addWidget(stage);status=new QComboBox(this);status->setObjectName("companyStatus");status->addItem("全部状态","");status->addItem("待核验 / 旧版本","review");status->addItem("当前人工已核验","manuallyVerified");status->addItem("有争议","disputed");toolbar->addWidget(status);search=new QLineEdit(this);search->setObjectName("companySearch");search->setPlaceholderText("公司 / 产品 / 完整代码");toolbar->addWidget(search,1);auto refresh=new QPushButton("重读本机资料",this);refresh->setObjectName("companyReload");toolbar->addWidget(refresh);root->addLayout(toolbar);
 auto split=new QSplitter(this);root->addWidget(split,1);auto views=new QTabWidget(split);table=new QTableWidget(0,6,views);table->setObjectName("researchCompanyTable");table->setHorizontalHeaderLabels({"公司 / 完整身份","产品","环节","状态","方向","来源"});table->setSelectionBehavior(QAbstractItemView::SelectRows);table->setSelectionMode(QAbstractItemView::SingleSelection);table->setEditTriggers(QAbstractItemView::NoEditTriggers);table->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);table->horizontalHeader()->setStretchLastSection(true);views->addTab(table,"公司清单");auto scroll=new QScrollArea(views);graph=new IndustryGraph(scroll);scroll->setWidget(graph);scroll->setWidgetResizable(true);views->addTab(scroll,"资料环节图");auto side=new QWidget(split);auto sl=new QVBoxLayout(side);reader=new QPlainTextEdit(side);reader->setObjectName("companyOriginal");reader->setReadOnly(true);sl->addWidget(reader,3);auto form=new QFormLayout;companyName=new QLineEdit(side);companyName->setObjectName("companyName");companyName->setMaxLength(200);product=new QLineEdit(side);product->setObjectName("companyProduct");product->setMaxLength(300);instrument=new QLineEdit(side);instrument->setObjectName("companyInstrument");instrument->setPlaceholderText("可不绑定；例 SH:stock:600000");identityDocument=new QComboBox(side);identityDocument->setObjectName("companyIdentityDocument");form->addRow("公司名",companyName);form->addRow("产品 / 环节内容",product);form->addRow("完整证券身份",instrument);form->addRow("身份依据资料",identityDocument);sl->addLayout(form);identityQuote=new QPlainTextEdit(side);identityQuote->setObjectName("companyIdentityQuote");identityQuote->setPlaceholderText("原文身份引文：公司名 + 独立代码 + 对应交易所。只记录原文，不推断主营/营收。");sl->addWidget(identityQuote,1);save=new QPushButton("保存选中关系的公司 / 产品",side);save->setObjectName("companySave");save->setEnabled(false);sl->addWidget(save);auto discard=new QPushButton("放弃本关系草稿",side);discard->setObjectName("companyDiscard");sl->addWidget(discard);connect(discard,&QPushButton::clicked,this,[this]{if(!isVisible()||!isEnabled()||!window()->isVisible()||window()->isMinimized()||QGuiApplication::applicationState()!=Qt::ApplicationActive)return;auto key=current["key"].toString();drafts.remove(key);select(key);persistDrafts();if(!property("sectorRelationDraftBlocked").toBool())state->setText("已放弃本关系草稿，恢复最新已保存内容。");});split->setSizes({800,440});state=new QLabel("选择当前主题与关系；原文引用和人工核验保持，旧版本只读。",this);state->setObjectName("companyState");state->setWordWrap(true);root->addWidget(state);
 connect(topics,&QComboBox::currentIndexChanged,this,[this]{if(rendering)return;reload();if(topicChanged)topicChanged(topics->currentData().toString());});for(auto box:{stage,status})connect(box,&QComboBox::currentIndexChanged,this,[this]{render();});connect(search,&QLineEdit::textChanged,this,[this]{render();});connect(refresh,&QPushButton::clicked,this,[this]{reload();});connect(table,&QTableWidget::cellClicked,this,[this](int row,int){if(row>=0&&row<visible.size())select(visible[row].toObject()["key"].toString());});graph->selected=[this](QString key){select(key);};connect(save,&QPushButton::clicked,this,[this]{if(!isVisible()||!isEnabled()||!window()->isVisible()||window()->isMinimized()||QGuiApplication::applicationState()!=Qt::ApplicationActive)return;saveCompany();});for(auto e:{companyName,product,instrument})connect(e,&QLineEdit::textChanged,this,[this]{captureDraft();});connect(identityQuote,&QPlainTextEdit::textChanged,this,[this]{captureDraft();});connect(identityDocument,&QComboBox::currentIndexChanged,this,[this]{captureDraft();});reload();QFile file(QFileInfo(store->filePath()).absolutePath()+"/research-company-drafts-v1.json");if(file.exists()&&file.size()<=4*1024*1024&&file.open(QIODevice::ReadOnly)){auto doc=QJsonDocument::fromJson(file.readAll());if(doc.isObject())restoreState(doc.object());}
}
void ResearchCompaniesPage::setTopic(QString id){reload();int at=topics->findData(id);if(at>=0){QSignalBlocker b(topics);topics->setCurrentIndex(at);reload();}}
void ResearchCompaniesPage::reload(){try{QString keep=topics->currentData().toString(),docId=identityDocument->currentData().toString();rendering=true;{QSignalBlocker t(topics),d(identityDocument);topics->clear();for(auto v:store->read("topics")){auto row=v.toObject();topics->addItem(row["name"].toString(),row["id"].toString());}topics->setCurrentIndex(std::max(0,topics->findData(keep)));identityDocument->clear();for(auto v:store->read("docs")){auto doc=v.toObject();identityDocument->addItem(doc["title"].toString(),doc["id"].toString());}if(identityDocument->findData(docId)>=0)identityDocument->setCurrentIndex(identityDocument->findData(docId));}auto projection=researchCompanies::project(topics->currentData().toString(),store->read("relations"),store->read("docs"),store->read("reports"));rows=projection["rows"].toArray();rendering=false;render();QStringList warnings;for(auto w:projection["warnings"].toArray())warnings<<w.toString();state->setText(QString("当前主题 %1 条关系；图只表达环节归属，旧核验不升级。%2").arg(rows.size()).arg(warnings.join("；")));}catch(const std::exception& e){rendering=false;state->setText(QString::fromUtf8(e.what()));}}
void ResearchCompaniesPage::render(){if(rendering)return;QString keep=current["key"].toString();visible={};table->setRowCount(0);auto needle=search->text().trimmed();for(auto v:rows){auto r=v.toObject();if(!stage->currentData().toString().isEmpty()&&r["stage"]!=stage->currentData().toString())continue;auto wanted=status->currentData().toString(),actual=r["status"].toString();if(wanted=="review"&&(actual=="manuallyVerified"||actual=="disputed"))continue;if(!wanted.isEmpty()&&wanted!="review"&&actual!=wanted)continue;auto hay=r["companyName"].toString()+r["product"].toString()+r["instrumentId"].toString()+r["company"].toObject()["stockCode"].toString();if(!hay.contains(needle,Qt::CaseInsensitive))continue;int row=table->rowCount();table->insertRow(row);QString id=r["instrumentId"].toString();if(id.isEmpty()&&!r["company"].toObject()["stockCode"].toString().isEmpty())id="旧代码 "+r["company"].toObject()["stockCode"].toString()+"（市场未绑定）";QStringList values{r["companyName"].toString()+"\n"+id,r["product"].toString(),researchCompanies::stageLabel(r["stage"].toString()),researchCompanies::statusLabel(actual),r["polarity"]=="contradicts"?"反证":"支持",r["readOnly"].toBool()?"归档版本":"本机原文"};for(int col=0;col<values.size();col++)table->setItem(row,col,new QTableWidgetItem(values[col]));visible.append(r);}graph->setRows(visible);bool retained=false;for(auto v:visible)if(v.toObject()["key"]==keep)retained=true;if(retained)select(keep);else{filling=true;current={};reader->clear();companyName->clear();product->clear();instrument->clear();identityQuote->clear();save->setEnabled(false);graph->setSelection({});filling=false;}}
void ResearchCompaniesPage::select(QString key){for(auto v:visible){auto row=v.toObject();if(row["key"]!=key)continue;filling=true;current=row;auto r=row["originalRecord"].toObject(),doc=row["originalDocument"].toObject(),c=r["company"].toObject();reader->setPlainText("状态："+researchCompanies::statusLabel(row["status"].toString())+"\n核验字段："+r["verification"].toString()+" / 旧状态："+r["status"].toString()+"\n原文完整性："+(row["bodyAvailable"].toBool()?"当前引用逐字匹配":"仅归档引用 / 当前全文不可得，未复核")+"\n关系："+r["claim"].toString()+"\n引用："+r["quote"].toString()+"\n证据引用："+QString::fromUtf8(QJsonDocument(r["evidenceRefs"].toArray()).toJson())+"\n资料："+doc["title"].toString()+"\n来源："+doc["sourceUrl"].toString()+"\n\n"+doc["text"].toString());companyName->setText(c["name"].toString());product->setText(r["product"].toString());instrument->setText(c["instrumentId"].toString());identityQuote->setPlainText(c["identityQuote"].toString());int at=identityDocument->findData(c["identityDocumentId"].toString());if(at>=0)identityDocument->setCurrentIndex(at);bool editable=!row["readOnly"].toBool();for(auto e:{companyName,product,instrument})e->setEnabled(editable);identityDocument->setEnabled(editable);identityQuote->setEnabled(editable);save->setEnabled(editable);auto draft=drafts[key].toObject();if(editable&&!draft.isEmpty()){companyName->setText(draft["name"].toString());product->setText(draft["product"].toString());instrument->setText(draft["instrument"].toString());identityQuote->setPlainText(draft["quote"].toString());int docIndex=identityDocument->findData(draft["documentId"].toString());if(docIndex>=0)identityDocument->setCurrentIndex(docIndex);}filling=false;graph->setSelection(key);for(int i=0;i<visible.size();i++)if(visible[i].toObject()["key"]==key)table->selectRow(i);return;}}
void ResearchCompaniesPage::saveCompany(){try{business::require(!current.isEmpty()&&!current["readOnly"].toBool(),"选择当前原生关系；旧版本只读");auto draft=drafts[current["key"].toString()].toObject();auto original=draft.isEmpty()?current["originalRecord"].toObject():draft["baseline"].toObject(),latest=QJsonObject{};for(auto v:store->read("relations"))if(v.toObject()["id"]==original["id"])latest=v.toObject();business::require(latest==original,"关系已变化，请重读，未覆盖其他修改");latest["product"]=product->text().trimmed();if(companyName->text().trimmed().isEmpty()){business::require(instrument->text().trimmed().isEmpty(),"先填公司名或清除身份");latest.remove("company");}else latest["company"]=QJsonObject{{"name",companyName->text().trimmed()},{"instrumentId",instrument->text().trimmed()},{"identityDocumentId",identityDocument->currentData().toString()},{"identityQuote",identityQuote->toPlainText().trimmed()}};store->save("relations",latest);drafts.remove(current["key"].toString());reload();persistDrafts();if(!property("sectorRelationDraftBlocked").toBool())state->setText("公司/产品已保存；原关系、引文与人工核验保持，没有改自选或账户。");}catch(const std::exception& e){state->setText(QString::fromUtf8(e.what()));}}

ResearchCompaniesPage::~ResearchCompaniesPage(){persistDrafts();}
void ResearchCompaniesPage::captureDraft(){if(filling||rendering||current.isEmpty()||current["readOnly"].toBool())return;auto key=current["key"].toString();auto existing=drafts[key].toObject();drafts[key]=QJsonObject{{"name",companyName->text()},{"product",product->text()},{"instrument",instrument->text()},{"quote",identityQuote->toPlainText()},{"documentId",identityDocument->currentData().toString()},{"baseline",existing.isEmpty()?current["originalRecord"]:existing["baseline"]}};state->setText("本关系有未保存草稿；筛选/重读不会覆盖，保存或显式放弃。关闭窗口时只保存本机草稿。");}
QJsonObject ResearchCompaniesPage::saveState()const{return {{"schema","research-company-drafts/v1"},{"topic",topics->currentData().toString()},{"selected",current["key"]},{"drafts",drafts},{"search",search->text()},{"stage",stage->currentIndex()},{"status",status->currentIndex()}};}
void ResearchCompaniesPage::restoreState(const QJsonObject& s){if(s["schema"]!="research-company-drafts/v1"||!s["drafts"].isObject()){state->setText("草稿格式无效，未替换当前输入。");return;}filling=true;drafts=s["drafts"].toObject();setTopic(s["topic"].toString());search->setText(s["search"].toString());stage->setCurrentIndex(std::clamp(s["stage"].toInt(),0,6));status->setCurrentIndex(std::clamp(s["status"].toInt(),0,3));render();select(s["selected"].toString());filling=false;state->setText("已恢复本机草稿，未自动保存公司关系。");}
void ResearchCompaniesPage::persistDrafts(){
 auto bytes=QJsonDocument(saveState()).toJson(QJsonDocument::Compact);if(bytes.size()>4*1024*1024){state->setText("草稿超过4MB，未写入；请保存或放弃部分草稿。");return;}
 auto path=property("sectorRelationDraftPath").toString();const bool embedded=!path.isEmpty();
 auto refuse=[this](const QString&issue){setProperty("sectorRelationDraftBlocked",true);setProperty("sectorRelationDraftIssue",issue);state->setText(issue);};
 if(embedded){
  if(property("sectorRelationDraftBlocked").toBool()){state->setText(property("sectorRelationDraftIssue").toString());return;}
  QFileInfo info(path);if(info.exists()!=property("sectorRelationDraftExpectedExists").toBool()){refuse("关系图草稿文件已由其他入口改变，原文件已保留；请重新打开后处理。");return;}
  if(info.exists()){QFile original(path);if(!info.isFile()||info.size()>4*1024*1024||!original.open(QIODevice::ReadOnly)){refuse("关系图草稿无法完整核对，原文件已保留，不会覆盖。");return;}auto prior=original.readAll();if(original.error()!=QFileDevice::NoError||prior.size()!=info.size()||QCryptographicHash::hash(prior,QCryptographicHash::Sha256)!=property("sectorRelationDraftExpectedHash").toByteArray()){refuse("关系图草稿内容已由其他入口改变，原文件已保留；请重新打开后处理。");return;}}
 }else path=QFileInfo(store->filePath()).absolutePath()+"/research-company-drafts-v1.json";
 QSaveFile file(path);if(!file.open(QIODevice::WriteOnly)||file.write(bytes)!=bytes.size()||!file.commit()){if(embedded)refuse("关系图草稿保存失败，原文件已保留；业务关系未因草稿写入而修改。");else state->setText("本机草稿保存失败，业务关系未修改。");return;}
 if(embedded){setProperty("sectorRelationDraftExpectedExists",true);setProperty("sectorRelationDraftExpectedHash",QCryptographicHash::hash(bytes,QCryptographicHash::Sha256));}
}
